const runs = $input.first().json.workflow_runs ?? [];
const now = Date.now();
const latest = new Map();
for (const r of runs) {
  if (!latest.has(r.name)) latest.set(r.name, r);
}
const checks = [...latest.values()].map(r => ({
  workflow: r.name, run_id: r.id, sha: r.head_sha ?? null,
  status: r.status, conclusion: r.conclusion ?? null,
  url: r.html_url ?? null,
  age_minutes: r.created_at ? Math.round((now - Date.parse(r.created_at))/60000) : null
}));
const failing = checks.filter(r => r.status === 'completed' && r.conclusion !== 'success' && r.conclusion !== 'skipped');
const stalled = checks.filter(r => r.status !== 'completed' && r.age_minutes !== null && r.age_minutes > 45);
const pending = checks.filter(r => r.status !== 'completed');
const next = failing.length ? 'INSPECT_FAILED_JOB_LOGS_AND_FIX' : stalled.length ? 'INSPECT_STALLED_WORKFLOWS' : pending.length ? 'WAIT_AND_RECHECK' : 'VERIFY_COUNCIL_PROVIDERS_ARTIFACT_AND_UI';
const status = failing.length || stalled.length ? 'FAIL' : pending.length ? 'RUNNING' : 'NOT_VERIFIED';
return [{json:{schema_version:1,observed_at:new Date(now).toISOString(),repository:'psw2025-cmd/Genesis_System3',lane:'LEGACY_ONLY',status,next_action:next,failures:failing,stalled,pending,checks,verified_workflow_count:checks.filter(r=>r.conclusion==='success').length,provider_review_verified:false,artifact_readback_verified:false,live_trading_allowed:false,latency_minutes:Math.max(0,...checks.map(r=>r.age_minutes??0))}}];
